using System;using System.Linq;
class ActionTimingTests {
 static int failures;static void Check(string name,bool ok){Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;}
 static int Main(){foreach(int frames in new[]{6,8,12}){int previous=-1,changes=0;double duration=ActionTiming.Duration("bowtie",frames,2.9);for(double t=0;t<duration;t+=.02){int f=ActionTiming.OneShot(frames,t,duration);if(f!=previous)changes++;CheckOnce(ref failures,f>=previous,"one-shot moved backwards");previous=f;}Check("one complete gesture "+frames,changes==frames&&previous==frames-1);Check("ends clamp "+frames,ActionTiming.OneShot(frames,duration+10,duration)==frames-1);}
  Check("kick duration fits full sequence",ActionTiming.Duration("kick",12,.4)>=1.68);Check("count remains brief",ActionTiming.Duration("count",20,.9)==.9);Check("all 20 specific number poses",Enumerable.Range(1,20).Select(n=>ActionTiming.NumberPose(n)).Distinct().Count()==20&&ActionTiming.NumberPose(20)==20);Check("random includes every new action",new[]{"deduction","watch","bowtie","kick","skate","count","praise","alert"}.All(x=>Array.IndexOf(ActionTiming.IdleActions,x)>=0));Check("random choices unique",ActionTiming.IdleActions.Distinct().Count()==ActionTiming.IdleActions.Length);
 Check("walking covers one stride per eight frames",ActionTiming.WalkFrame(84,1)==7&&ActionTiming.WalkFrame(96,1)==0);Check("scaled stride keeps same phase",ActionTiming.WalkFrame(168,2)==7);Check("old stride does not rapidly restart legs",ActionTiming.WalkFrame(64,1)==5);Check("scaled gait phase is unchanged",Math.Abs(ActionTiming.WalkPhase(70,1)-ActionTiming.WalkPhase(140,2))<.00001);Check("skate travels faster than feet",ActionTiming.TravelSpeed(1,true)>2*ActionTiming.TravelSpeed(1,false));Check("scaled character travels proportionally",ActionTiming.TravelSpeed(2,false)==2*ActionTiming.TravelSpeed(1,false));Check("moving is not interrupted by idle",!ActionTiming.CanIdle(10,15)&&ActionTiming.CanIdle(15,15));
 Console.WriteLine("Failures: "+failures);return failures==0?0:1;}
 static void CheckOnce(ref int failures,bool ok,string name){if(!ok){Console.WriteLine("FAIL "+name);failures++;}}
}
